package vn.smartfarm.iot.irrigation;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.sql.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.annotation.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.control.PumpCircuitRoute;

/** One reviewed simulator session, five durable steps. No retry, resume, route switch or queue dispatch. */
@Service
public class IrrigationCycle {
 public record Arm(UUID armId,long expectedRevision,Instant reviewedAt) {}
 public record Cycle(UUID sessionId,UUID armId,Arm definition,UUID openId,UUID onId,UUID offId,UUID closeId,UUID finishId,Instant armedAt,Instant deadline,Instant stepDeadline,Instant stopAt,String stopReason,String state,String reason,Instant finishedAt) {}
 public record View(String mode,String circuitId,UUID sessionId,Instant asOf,long sessionRevision,String phase,int durationSeconds,boolean enabled,boolean canArm,String reason,Cycle cycle) {}
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IrrigationSession sessions;private final TransactionTemplate tx;private final boolean enabled;
 public IrrigationCycle(JdbcTemplate jdbc,ObjectMapper mapper,IrrigationSession sessions,PlatformTransactionManager manager,@Value("${smartfarm.irrigation.cycle-enabled:false}")boolean enabled){this.jdbc=jdbc;this.mapper=mapper;this.sessions=sessions;this.tx=new TransactionTemplate(manager);this.enabled=enabled;}
 boolean available(){return enabled&&sessions.closureReady();}
 private void gates(){jdbc.queryForObject("SELECT singleton FROM pump_dispatch_gate WHERE singleton=1 FOR UPDATE",Integer.class);jdbc.queryForObject("SELECT revision FROM irrigation_circuit_state WHERE singleton=1 FOR UPDATE",Long.class);}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 private Arm decode(String text){try{return mapper.readValue(text,Arm.class);}catch(Exception e){throw new IllegalStateException(e);}}
 private static Instant at(ResultSet r,String field)throws SQLException{var t=r.getTimestamp(field);return t==null?null:t.toInstant();}
 private Cycle map(ResultSet r,int n)throws SQLException{return new Cycle(r.getObject("session_id",UUID.class),r.getObject("arm_id",UUID.class),decode(r.getString("definition")),r.getObject("open_id",UUID.class),r.getObject("on_id",UUID.class),r.getObject("off_id",UUID.class),r.getObject("close_id",UUID.class),r.getObject("finish_id",UUID.class),at(r,"armed_at"),at(r,"deadline"),at(r,"step_deadline"),at(r,"stop_at"),r.getString("stop_reason"),r.getString("state"),r.getString("reason"),at(r,"finished_at"));}
 private Cycle find(UUID session){return jdbc.query("SELECT * FROM irrigation_session_cycle WHERE session_id=?",this::map,session).stream().findFirst().orElse(null);}
 private boolean binding(IrrigationSession.Run r,IrrigationSession.View v){var p=v.pump().commandFence();var i=p.intent();return r.config().expectedSource().equals("SIMULATOR")&&r.config().equals(v.valve().config())&&v.valve().latest()!=null&&v.valve().latest().config().equals(r.config())&&v.valve().latest().bootId().equals(r.valveBootId())&&i!=null&&Objects.equals(i.bootId(),r.pumpBootId())&&v.enabled()&&v.valve().enabled()&&v.pump().controlEnabled()&&p.required()&&p.compatible()&&!p.restartRequired()&&p.circuitRouteRequired()&&PumpCircuitRoute.from(r.config()).equals(p.circuitRoute())&&v.valve().configurationState().equals("CURRENT");}
 private String armReason(IrrigationSession.Run r,IrrigationSession.View v){if(!enabled||!sessions.closureReady())return "PROFILE_DISABLED";if(!r.phase().equals("PREPARED")||r.stopRequested()||r.openId()!=null||r.onId()!=null||r.offId()!=null)return "PREPARED_SESSION_REQUIRED";if(jdbc.queryForObject("SELECT count(*) FROM irrigation_session_closure WHERE session_id=?",Integer.class,r.sessionId())>0)return "CLOSURE_ALREADY_DEFINED";if(!binding(r,v)||v.active()==null||!v.active().sessionId().equals(r.sessionId())||!v.canOpen())return "CIRCUIT_NOT_READY";return "READY";}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public View snapshot(String circuit,UUID session){var r=sessions.find(circuit,session);var c=find(session);String reason=c==null?armReason(r,sessions.snapshot(circuit)):c.reason();return new View("SINGLE_SESSION_CYCLE",circuit,session,Instant.now(),r.revision(),r.phase(),r.durationSeconds(),enabled,c==null&&reason.equals("READY"),reason,c);}
 public Cycle arm(String circuit,UUID session,Arm raw){if(raw==null||raw.armId()==null||raw.expectedRevision()<1||raw.expectedRevision()>9007199254740991L||raw.reviewedAt()==null)throw bad("Invalid cycle arm");var a=new Arm(raw.armId(),raw.expectedRevision(),raw.reviewedAt().truncatedTo(ChronoUnit.MICROS));return tx.execute(t->{gates();var r=sessions.find(circuit,session);var old=find(session);if(old!=null){if(!old.definition().equals(a))throw conflict("Cycle already has a one-shot definition");return old;}var now=Instant.now().truncatedTo(ChronoUnit.MICROS);if(a.expectedRevision()!=r.revision()||a.reviewedAt().isBefore(now.minusSeconds(10))||a.reviewedAt().isAfter(now.plusSeconds(2))||!armReason(r,sessions.snapshot(circuit)).equals("READY"))throw conflict("Review current prepared session and proofs");jdbc.update("INSERT INTO irrigation_session_cycle(session_id,arm_id,definition,open_id,on_id,off_id,close_id,finish_id,armed_at,deadline,state,reason) VALUES(?,?,?::jsonb,?,?,?,?,?,?,?,'ARMED','WAIT_FIRST_STEP')",session,a.armId(),json(a),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),Timestamp.from(now),Timestamp.from(now.plusSeconds(30)));return find(session);});}
 public Cycle pause(String circuit,UUID session,UUID arm){if(arm==null)throw bad("Arm ID required");return tx.execute(t->{gates();sessions.find(circuit,session);var c=find(session);if(c==null||!c.armId().equals(arm))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Cycle not found");end(c,"PAUSED","OPERATOR_PAUSED",true);return find(session);});}
 private void end(Cycle c,String state,String reason,boolean recover){if(c.finishedAt()!=null)return;jdbc.update("UPDATE irrigation_session_cycle SET state=?,reason=?,finished_at=CURRENT_TIMESTAMP WHERE session_id=? AND finished_at IS NULL",state,reason,c.sessionId());if(recover)jdbc.update("UPDATE irrigation_session SET phase='RECOVERY_REQUIRED',stop_requested=true,reason=?,revision=revision+1 WHERE session_id=? AND phase<>'CLOSED_CONFIRMED'","CYCLE_"+reason,c.sessionId());}
 private String ledger(UUID id,String action){return Set.of("ON","OFF").contains(action)?jdbc.query("SELECT state FROM pump_command WHERE command_id=? AND action=?",(r,n)->r.getString(1),id,action).stream().findFirst().orElse("MISSING"):jdbc.query("SELECT state FROM circuit_demo_command WHERE command_id=? AND action=?",(r,n)->r.getString(1),id,action).stream().findFirst().orElse("MISSING");}
 private boolean offAck(IrrigationSession.Run r){return jdbc.queryForObject("SELECT count(*) FROM pump_command c JOIN pump_status s ON s.singleton=1 WHERE c.command_id=? AND c.action='OFF' AND c.state='EXECUTED' AND c.reported_state='OFF' AND c.ack_boot_id=? AND c.ack_sequence IS NOT NULL AND c.acknowledged_at IS NOT NULL AND s.boot_id=c.ack_boot_id AND s.sequence>c.ack_sequence AND s.last_fence_ordinal>=c.fence_ordinal",Integer.class,r.offId(),r.pumpBootId())==1;}
 private boolean onProof(IrrigationSession.Run r,IrrigationSession.View v){return v.pump().fresh()&&v.pump().reportedState().equals("ON")&&!v.pump().safetyLockout()&&jdbc.queryForObject("SELECT count(*) FROM pump_command c JOIN pump_status s ON s.singleton=1 WHERE c.command_id=? AND c.action='ON' AND c.state='EXECUTED' AND c.reported_state='ON' AND c.ack_boot_id=? AND c.acknowledged_at IS NOT NULL AND s.boot_id=c.ack_boot_id AND s.sequence>c.ack_sequence AND s.last_fence_ordinal>=c.fence_ordinal AND s.observed_at>=c.issued_at",Integer.class,r.onId(),r.pumpBootId())==1;}
 private record Step(Cycle cycle,String circuit,String action,long revision,String expectedState,String stopReason) {}
 public void poll(){if(!enabled||!sessions.closureReady())return;for(var c:jdbc.query("SELECT * FROM irrigation_session_cycle WHERE finished_at IS NULL",this::map))advance(c);}
 private void advance(Cycle expected){var step=tx.execute(t->{gates();var c=find(expected.sessionId());if(c==null||c.finishedAt()!=null||!c.armId().equals(expected.armId()))return null;String circuit=jdbc.queryForObject("SELECT circuit_id FROM irrigation_session WHERE session_id=?",String.class,c.sessionId());var r=sessions.find(circuit,c.sessionId());var v=sessions.snapshot(circuit);var now=Instant.now();boolean ownOn=c.onId().equals(r.onId());
  if(r.phase().equals("CLOSED_CONFIRMED")||r.offId()!=null&&!r.offId().equals(c.offId())||r.reason().equals("EXTERNAL_OFF")){end(c,"INTERRUPTED","SESSION_TAKEN_OVER",false);return null;}
  boolean needsStop=ownOn&&r.offId()==null&&Set.of("ON_RESERVED","WAIT_ON","RUNNING").contains(c.state());
  String stop=needsStop?(!c.deadline().isAfter(now)?"CYCLE_DEADLINE":!binding(r,v)?"BINDING_CHANGED":!c.stopAt().isAfter(now)?"DURATION_REACHED":c.state().equals("WAIT_ON")&&!Set.of("SENT","EXECUTED").contains(ledger(c.onId(),"ON"))?"ON_OUTCOME_UNRESOLVED":c.state().equals("WAIT_ON")&&!c.stepDeadline().isAfter(now)&&!onProof(r,v)?"ON_PROOF_TIMEOUT":c.state().equals("RUNNING")&&(!onProof(r,v)||!PumpCircuitRoute.inspect(jdbc,mapper,PumpCircuitRoute.from(r.config()),false).ready())?"RUNNING_PROOF_LOST":null):null;
  if(stop!=null)return new Step(c,circuit,"OFF",r.revision(),c.state(),stop);
  if(!c.deadline().isAfter(now)){end(c,"EXPIRED","CYCLE_DEADLINE",true);return null;}
  if(!binding(r,v)){end(c,"INTERRUPTED","BINDING_CHANGED",true);return null;}
  if(c.state().endsWith("_RESERVED"))return null; // in-flight reservation is never replayed
  if(c.state().equals("ARMED")){if(!v.canOpen()){end(c,"INTERRUPTED","START_READINESS_CHANGED",true);return null;}return new Step(c,circuit,"OPEN",r.revision(),c.state(),null);}
  if(c.state().equals("WAIT_OPEN")){
   if(!Set.of("SENT","EXECUTED").contains(ledger(c.openId(),"OPEN"))){end(c,"UNRESOLVED","OPEN_OUTCOME_UNRESOLVED",true);return null;}
   if(!vn.smartfarm.iot.nodes.CircuitWaterGate.inspect(jdbc,circuit,now).allowed()||!vn.smartfarm.iot.nodes.ZoneRainGate.inspect(jdbc,r.config().zoneId(),now).allowed()){end(c,"INTERRUPTED","ADMISSION_CHANGED",true);return null;}
   if(!c.stepDeadline().isAfter(now)){end(c,"EXPIRED","OPEN_PROOF_TIMEOUT",true);return null;}if(v.canOn())return new Step(c,circuit,"ON",r.revision(),c.state(),null);
  }
  if(c.state().equals("WAIT_ON")&&onProof(r,v))jdbc.update("UPDATE irrigation_session_cycle SET state='RUNNING',reason='ON_ACK_AND_STATUS_CONFIRMED' WHERE session_id=?",c.sessionId());
  if(c.state().equals("WAIT_OFF")){if(!Set.of("SENT","EXECUTED").contains(ledger(c.offId(),"OFF"))){end(c,"UNRESOLVED","OFF_OUTCOME_UNRESOLVED",true);return null;}if(v.canClose()&&offAck(r))return new Step(c,circuit,"CLOSE",r.revision(),c.state(),null);}
  if(c.state().equals("WAIT_CLOSED")){if(!Set.of("SENT","EXECUTED").contains(ledger(c.closeId(),"CLOSE"))){end(c,"UNRESOLVED","CLOSE_OUTCOME_UNRESOLVED",true);return null;}if(v.canFinish()&&offAck(r))return new Step(c,circuit,"FINISH",r.revision(),c.state(),null);}
  return null;
 });if(step!=null)dispatch(step);}
 private UUID id(Cycle c,String action){return switch(action){case "OPEN"->c.openId();case "ON"->c.onId();case "OFF"->c.offId();case "CLOSE"->c.closeId();default->c.finishId();};}
 private Cycle checked(Step s,String state){var c=find(s.cycle().sessionId());if(!enabled||!sessions.closureReady()||c==null||c.finishedAt()!=null||!c.armId().equals(s.cycle().armId())||!c.state().equals(state)||!s.action().equals("OFF")&&!c.deadline().isAfter(Instant.now()))throw conflict("Cycle superseded or expired");return c;}
 private void dispatch(Step s){var original=s.cycle();String action=s.action();UUID id=id(original,action);try{
  var receipt=sessions.actForCycle(s.circuit(),original.sessionId(),new IrrigationSession.Action(id,action,s.revision(),Instant.now()),()->{
   var c=checked(s,s.expectedState());var r=sessions.find(s.circuit(),c.sessionId());if(r.revision()!=s.revision()||action.equals("OFF")&&r.offId()!=null)throw conflict("Session changed before cycle step");if(Set.of("CLOSE","FINISH").contains(action)&&!offAck(r))throw conflict("OFF proof changed");if(!action.equals("OFF")&&!binding(r,sessions.snapshot(s.circuit())))throw conflict("Cycle binding changed");
   Instant now=Instant.now();jdbc.update("UPDATE irrigation_session_cycle SET state=?,reason=?,step_deadline=?,stop_at=COALESCE(stop_at,?),stop_reason=COALESCE(stop_reason,?),finished_at=? WHERE session_id=?",action.equals("FINISH")?"COMPLETE":action+"_RESERVED",action.equals("FINISH")?"OFF_AND_CLOSED_CONFIRMED":"WAIT_"+action+"_RESULT",Timestamp.from(now.plusSeconds(action.equals("ON")?5:10)),action.equals("ON")?Timestamp.from(now.plusSeconds(r.durationSeconds())):null,s.stopReason(),action.equals("FINISH")?Timestamp.from(now):null,c.sessionId());
  },()->{
   var c=checked(s,action+"_RESERVED");var r=sessions.find(s.circuit(),c.sessionId());if(!r.phase().equals("DISPATCHING_"+action)||!Objects.equals(id,id(c,action))||!Objects.equals(id,switch(action){case "OPEN"->r.openId();case "ON"->r.onId();case "OFF"->r.offId();default->r.closeId();}))throw conflict("Cycle dispatch superseded");
   if(action.equals("CLOSE")&&!offAck(r))throw conflict("OFF proof changed before CLOSE commit");if(!action.equals("OFF")&&(!binding(r,sessions.snapshot(s.circuit()))||action.equals("ON")&&!c.stopAt().isAfter(Instant.now())))throw conflict("Cycle no longer permits this step");
  });
  if(!action.equals("FINISH"))tx.executeWithoutResult(t->{gates();var c=find(original.sessionId());if(c!=null&&c.finishedAt()==null&&c.state().equals(action+"_RESERVED")){
   if(receipt.operation().state().equals("RETURNED")||action.equals("ON"))jdbc.update("UPDATE irrigation_session_cycle SET state=?,reason=? WHERE session_id=?",action.equals("CLOSE")?"WAIT_CLOSED":"WAIT_"+action,"CHECK_DEVICE_EVIDENCE",c.sessionId());else end(c,"UNRESOLVED",action+"_OUTCOME_UNRESOLVED",true);
  }});
 }catch(ResponseStatusException ignored){/* Re-evaluate unreserved transitions only. Never replay committed identities. */}}
 private static ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);}
 private static ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}
}
